describe('Modal Dialog - Focus Management on Close', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
    cy.get('[data-testid="modal-trigger"]').as('triggerButton');
    cy.get('[data-testid="modal"]').as('modal');
    cy.get('[data-testid="modal-close-button"]').as('closeButton');
  });

  it('should return focus to trigger button when modal closes via close button', () => {
    // Open modal
    cy.get('@triggerButton').click();

    // Verify modal is visible
    cy.get('@modal').should('be.visible');

    // Verify focus is within modal
    cy.get('@modal').should('have.focus').or('contain.focus');

    // Close modal via close button
    cy.get('@closeButton').click();

    // Verify modal is closed
    cy.get('@modal').should('not.be.visible');

    // Verify focus returns to trigger button
    cy.get('@triggerButton').should('have.focus');
  });

  it('should return focus to trigger button when modal closes via escape key', () => {
    // Open modal
    cy.get('@triggerButton').click();

    // Verify modal is visible
    cy.get('@modal').should('be.visible');

    // Close modal via escape key
    cy.get('body').type('{esc}');

    // Verify modal is closed
    cy.get('@modal').should('not.be.visible');

    // Verify focus returns to trigger button
    cy.get('@triggerButton').should('have.focus');
  });

  it('should return focus to trigger button when modal closes via backdrop click', () => {
    // Open modal
    cy.get('@triggerButton').click();

    // Verify modal is visible
    cy.get('@modal').should('be.visible');

    // Click on backdrop to close modal
    cy.get('[data-testid="modal-backdrop"]').click({ force: true });

    // Verify modal is closed
    cy.get('@modal').should('not.be.visible');

    // Verify focus returns to trigger button
    cy.get('@triggerButton').should('have.focus');
  });

  it('should maintain focus trap while modal is open and restore focus on close', () => {
    // Open modal
    cy.get('@triggerButton').click();

    // Verify modal is visible
    cy.get('@modal').should('be.visible');

    // Tab through focusable elements within modal
    cy.get('[data-testid="modal-input"]').focus();
    cy.get('[data-testid="modal-input"]').should('have.focus');

    // Tab to next element
    cy.get('[data-testid="modal-input"]').tab();
    cy.get('[data-testid="modal-confirm-button"]').should('have.focus');

    // Close modal
    cy.get('@closeButton').click();

    // Verify modal is closed
    cy.get('@modal').should('not.be.visible');

    // Verify focus returns to trigger button
    cy.get('@triggerButton').should('have.focus');
  });

  it('should handle rapid open/close cycles with correct focus management', () => {
    // First cycle
    cy.get('@triggerButton').click();
    cy.get('@modal').should('be.visible');
    cy.get('@closeButton').click();
    cy.get('@modal').should('not.be.visible');
    cy.get('@triggerButton').should('have.focus');

    // Second cycle
    cy.get('@triggerButton').click();
    cy.get('@modal').should('be.visible');
    cy.get('@closeButton').click();
    cy.get('@modal').should('not.be.visible');
    cy.get('@triggerButton').should('have.focus');

    // Third cycle
    cy.get('@triggerButton').click();
    cy.get('@modal').should('be.visible');
    cy.get('@closeButton').click();
    cy.get('@modal').should('not.be.visible');
    cy.get('@triggerButton').should('have.focus');
  });

  it('should restore focus even when trigger button is disabled after modal opens', () => {
    // Open modal
    cy.get('@triggerButton').click();
    cy.get('@modal').should('be.visible');

    // Disable trigger button while modal is open
    cy.get('@triggerButton').invoke('attr', 'disabled', 'disabled');

    // Close modal
    cy.get('@closeButton').click();
    cy.get('@modal').should('not.be.visible');

    // Verify focus management still works (focus should attempt to return)
    cy.get('@triggerButton').should('have.focus');
  });
});
